const now = new Date();
const p2 = (n) => String(n).padStart(2, '0');
const offset = (month) => { const m = -new Date(2025, month, 1).getTimezoneOffset(); return (m < 0 ? '-' : '+') + p2(Math.floor(Math.abs(m) / 60)) + ':' + p2(Math.abs(m) % 60); };
console.log('Time zone:  ' + Intl.DateTimeFormat().resolvedOptions().timeZone);
console.log('UTC offset: ' + offset(0) + ' in January, ' + offset(6) + ' in July');
console.log('Local day:  ' + now.getFullYear() + '-' + p2(now.getMonth() + 1) + '-' + p2(now.getDate()));
console.log('UTC day:    ' + now.toISOString().slice(0, 10));
